import { NextRequest, NextResponse } from 'next/server';

const STRAPI_URL = process.env.NEXT_PUBLIC_STRAPI_URL || 'http://localhost:1337';
const STRAPI_API_TOKEN = process.env.STRAPI_API_TOKEN;

export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData();
    const testFile = formData.get('file') as File;

    if (!testFile) {
      return NextResponse.json({
        success: false,
        error: 'No file provided'
      }, { status: 400 });
    }

    console.log('Testing upload with file:', {
      name: testFile.name,
      size: testFile.size,
      type: testFile.type
    });

    // Create FormData for Strapi
    const strapiFormData = new FormData();
    strapiFormData.append('files', testFile);

    // Test different upload endpoints
    const endpoints = [
      `${STRAPI_URL}/api/upload`,
      `${STRAPI_URL}/upload`,
      `${STRAPI_URL}/api/upload/files`
    ];

    const results = [];

    for (const endpoint of endpoints) {
      try {
        console.log(`Testing endpoint: ${endpoint}`);
        
        const response = await fetch(endpoint, {
          method: 'POST',
          headers: {
            ...(STRAPI_API_TOKEN && { Authorization: `Bearer ${STRAPI_API_TOKEN}` }),
          },
          body: strapiFormData,
        });

        const responseText = await response.text();
        let responseData;
        
        try {
          responseData = JSON.parse(responseText);
        } catch {
          responseData = responseText;
        }

        results.push({
          endpoint,
          status: response.status,
          statusText: response.statusText,
          success: response.ok,
          data: responseData,
          headers: Object.fromEntries(response.headers.entries())
        });

        console.log(`Endpoint ${endpoint} result:`, {
          status: response.status,
          success: response.ok
        });

        // If successful, break
        if (response.ok) {
          break;
        }

      } catch (error) {
        results.push({
          endpoint,
          status: 'ERROR',
          error: error instanceof Error ? error.message : String(error)
        });
      }
    }

    return NextResponse.json({
      success: results.some(r => r.success),
      results,
      environment: {
        STRAPI_URL,
        hasApiToken: !!STRAPI_API_TOKEN,
        tokenPreview: STRAPI_API_TOKEN ? `${STRAPI_API_TOKEN.substring(0, 10)}...` : 'Not set'
      }
    });

  } catch (error) {
    console.error('Upload test error:', error);
    return NextResponse.json({
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

export async function GET() {
  return NextResponse.json({
    message: 'Upload test endpoint. Use POST with a file to test upload functionality.',
    usage: 'POST with FormData containing a "file" field'
  });
}